{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Sessions — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fcfbf7;--card:#fff8f0;--ink:#2b2b2b;--muted:#6f6b64;--accent:#9b6b3d;--accent-2:#6b8a5f}
    *{box-sizing:border-box}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;line-height:1.4;color:var(--ink);margin:0;background:linear-gradient(180deg,var(--bg),#f8f4ee)}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 24px;border-bottom:1px solid #efe9e1;background:rgba(255,255,255,0.6);backdrop-filter:blur(4px)}
    .brand{display:flex;gap:12px;align-items:center}
    .logo{width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none;font-size:0.95rem}
    .wrap{max-width:960px;margin:28px auto;padding:0 20px}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:20px;align-items:start}
    .panel{background:var(--card);padding:20px;border-radius:12px;box-shadow:0 6px 20px rgba(95,70,50,0.08)}
    h1{margin:0 0 8px;font-size:1.6rem}
    p.lead{margin:0 0 14px;color:var(--muted)}
    .small{font-size:0.9rem;color:var(--muted)}
    .session-list{display:flex;flex-direction:column;gap:12px;margin-top:12px}
    .session{padding:12px;border-radius:8px;border:1px dashed #efe0d6;background:linear-gradient(180deg,#fff,#fffaf6)}
    .session h3{margin:0 0 6px;font-size:1rem}
    .session p{margin:0;color:var(--muted);font-size:0.93rem}
    /* Planner */
    .planner h3{margin-top:0}
    .form-row{display:flex;gap:8px;margin-bottom:10px}
    .form-row select,.form-row input,.form-row textarea{flex:1;padding:8px;border-radius:6px;border:1px solid #e6ded4}
    .btn{display:inline-block;padding:10px 14px;background:var(--accent);color:#fff;border-radius:8px;text-decoration:none;border:none;font-weight:600}
    .secondary{background:#fff;border:1px solid #e6ded4;color:var(--ink}
    .output{white-space:pre-wrap;background:#fff;border-radius:8px;padding:12px;border:1px solid #efe6dd;height:160px;overflow:auto}
    footer{max-width:960px;margin:28px auto;padding:14px 20px;color:var(--muted);font-size:0.9rem}
    .faq{display:grid;grid-template-columns:1fr 1fr;gap:12px}
    .faq .q{background:#fff;padding:12px;border-radius:8px;border:1px solid #efe6dd}
    .cta-row{display:flex;gap:12px;align-items:center;margin-top:12px}
    .note{font-size:0.85rem;color:var(--muted)}
    @media(max-width:880px){.hero{grid-template-columns:1fr}.planner{order:2}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">A</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:0.85rem;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Welcome</a>
      <a href="services.html">Sessions</a>
      <a href="blends.html">Blends Lab</a>
      <a href="shop.html">Herbarium Shop</a>
      <a href="pricing.html">Plans</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Reach</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="hero">
      <div class="panel">
        <h1>Care Sessions and Tailored Rituals</h1>
        <p class="lead">Short, guided aromatherapy sessions designed to be practical and safety-forward. Each session may support relaxation, focus, or ease at different parts of your day.</p>

        <div class="session-list">
          <div class="session">
            <h3>Renew — 30 minutes</h3>
            <p>Brief intake, aroma selection, guided breathing cues, and an at-home plan you can repeat.</p>
          </div>

          <div class="session">
            <h3>Deep Care — 75 minutes</h3>
            <p>Extended consultation, custom blend creation, technique teaching, and reflections to support a weekly rhythm.</p>
          </div>

          <div class="session">
            <h3>Mini Membership Check-in — 20 minutes</h3>
            <p>Monthly touchpoint for members to refine blends and receive safe dilution reminders.</p>
          </div>
        </div>

        <div class="cta-row">
          <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn" style="background:var(--accent-2)" href="pricing.html">Explore Care Circles</a>
        </div>
      </div>

      <aside class="panel planner">
        <h3>Session Planner — build a small-care plan</h3>
        <div class="note">Quickly assemble a safe, personalized session plan. Use the copy button to save or paste into notes.</div>
        <div style="height:12px"></div>
        <div class="form-row">
          <select id="goal">
            <option value="relax">I want to relax (calm)</option>
            <option value="focus">I want to focus (clarity)</option>
            <option value="sleep">I want help winding down</option>
            <option value="uplift">I want gentle uplift</option>
          </select>
        </div>
        <div class="form-row">
          <select id="duration">
            <option value="10">10 minutes</option>
            <option value="20">20 minutes</option>
            <option value="30">30 minutes</option>
            <option value="45">45 minutes</option>
          </select>
          <select id="frequency">
            <option value="daily">Daily</option>
            <option value="3x_week">3× per week</option>
            <option value="weekly">Weekly</option>
          </select>
        </div>
        <div class="form-row">
          <select id="sensitivity">
            <option value="normal">No known sensitivities</option>
            <option value="skin">Sensitive skin</option>
            <option value="preg">Pregnant or breastfeeding</option>
            <option value="pets">Have household pets</option>
          </select>
        </div>
        <div class="form-row">
          <input id="notes" placeholder="Any notes (allergies, favorite scents)" />
        </div>
        <div style="display:flex;gap:8px;align-items:center;margin-bottom:10px">
          <button class="btn" id="build">Create Plan</button>
          <button class="btn" id="clear" style="background:#fff;color:var(--ink);border:1px solid #e6ded4">Reset</button>
        </div>

        <div class="output" id="planOutput">Your personalized plan will appear here.
</div>
        <div style="display:flex;gap:8px;margin-top:8px">
          <button class="btn" id="copyPlan">Copy Plan</button>
          <a class="btn" style="background:var(--accent-2)" href="book.html">Book a guided session</a>
        </div>
      </aside>
    </section>

    <section style="margin-top:18px;display:grid;grid-template-columns:1fr 320px;gap:20px">
      <div class="panel">
        <h2>What to expect in a session</h2>
        <p class="small">Sessions center your preferences, safety notes, and the latest safe dilution guidance. We focus on sensory cues, simple rituals, and repeatable practices you can do at home.</p>

        <h3 style="margin-top:12px">Sample session flow</h3>
        <ol style="margin:8px 0 0 18px;color:var(--muted)">
          <li>Short intake and safety review (patch-test, pets, pregnancy)</li>
          <li>Co-create a scent profile and select oils</li>
          <li>Teach a short ritual and breathing sequence</li>
          <li>Provide a written plan with dilution guide</li>
        </ol>

        <h3 style="margin-top:12px">Membership benefit</h3>
        <p class="small">Members receive monthly check-ins, exclusive micro-blends, and practical dilution reminders tailored to home life.</p>
      </div>

      <aside class="panel">
        <h3>Quick FAQ</h3>
        <div class="faq">
          <div class="q">
            <strong>Are these medical treatments?</strong>
            <p class="small">No. Aromatherapy may support well-being but is not a substitute for medical care.</p>
          </div>
          <div class="q">
            <strong>Safety and dilution</strong>
            <p class="small">Every plan recommends safe dilution ranges and a patch test. We avoid high-risk oils for pregnancy and certain household pets.</p>
          </div>
          <div class="q">
            <strong>Pets at home?</strong>
            <p class="small">Tell us about pets in intake. Some oils should not be used around cats or birds; we will suggest alternatives.</p>
          </div>
          <div class="q">
            <strong>Pregnancy and breastfeeding</strong>
            <p class="small">Certain oils are not recommended during pregnancy or breastfeeding. We will offer safe possibilities and always err on caution.</p>
          </div>
        </div>
      </aside>
    </section>

  </main>

  <footer>
    <div style="max-width:960px;margin:0 auto;padding:0 20px;display:flex;justify-content:space-between;align-items:center">
      <div class="small">Serving {{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}" style="color:inherit">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}" style="color:inherit">{{EMAIL}}</a></div>
      <div class="small">© <span id="year"></span> All rights reserved</div>
    </div>
  </footer>

  <script>
    document.getElementById('year').textContent = new Date().getFullYear();

    function buildPlan(){
      const goal = document.getElementById('goal').value;
      const duration = document.getElementById('duration').value;
      const frequency = document.getElementById('frequency').value;
      const sensitivity = document.getElementById('sensitivity').value;
      const notes = document.getElementById('notes').value.trim();

      const oilsByGoal = {
        relax:['Lavender','Sweet Marjoram','Roman Chamomile'],
        focus:['Rosemary (cineole)','Basil','Grapefruit'],
        sleep:['Lavender','Vetiver','Cedarwood'],
        uplift:['Sweet Orange','Bergamot','Ginger']
      };

      const selectedOils = oilsByGoal[goal].slice(0,3).join(', ');

      const dilution = (sensitivity==='skin') ? '0.5-1%' : (sensitivity==='preg') ? '0.5%' : '1-2%';
      const dropsPer10ml = (dilution==='0.5-1%') ? '1-2 drops per 10 mL' : (dilution==='0.5%') ? '1 drop per 10 mL' : '3-6 drops per 10 mL';

      let plan = `Personal Care Plan\n\nGoal: ${goal}\nDuration: ${duration} minutes\nFrequency: ${frequency}\n\nSuggested oils: ${selectedOils}\nRecommended dilution: ${dilution} (${dropsPer10ml})\n\nSession outline:\n- Intake and safety review (patch test advised)\n- Aroma selection and brief guided practice\n- At-home repetition: ${frequency} for ${duration} minutes\n`;

      if(notes) plan += `\nNotes: ${notes}\n`;
      plan += `\nSafety note: This plan may support comfort and routine. Not medical advice. Avoid use near sensitive pets; consult a qualified provider for clinical concerns.`;

      return plan;
    }

    document.getElementById('build').addEventListener('click', ()=>{
      document.getElementById('planOutput').textContent = buildPlan();
    });

    document.getElementById('copyPlan').addEventListener('click', async ()=>{
      try{
        await navigator.clipboard.writeText(document.getElementById('planOutput').textContent);
        alert('Plan copied to clipboard');
      }catch(e){
        alert('Copy failed — select and copy manually');
      }
    });

    document.getElementById('clear').addEventListener('click', ()=>{
      document.getElementById('goal').value='relax';
      document.getElementById('duration').value='10';
      document.getElementById('frequency').value='daily';
      document.getElementById('sensitivity').value='normal';
      document.getElementById('notes').value='';
      document.getElementById('planOutput').textContent = 'Your personalized plan will appear here.';
    });
  </script>
</body>
</html>"} 
